from flask import jsonify
from werkzeug.exceptions import HTTPException


def register_error_handlers(app):
    @app.errorhandler(HTTPException)
    def handle_http_exception(error):
        response = {
            "error": error.name,
            "message": error.description,
        }
        return jsonify(response), error.code

    @app.errorhandler(404)
    def handle_not_found(error):
        return jsonify({"error": "Not Found", "message": "Resource not found"}), 404

    @app.errorhandler(405)
    def handle_method_not_allowed(error):
        return jsonify({"error": "Method Not Allowed", "message": str(error)}), 405

    @app.errorhandler(400)
    def handle_bad_request(error):
        return jsonify({"error": "Bad Request", "message": str(error)}), 400

    @app.errorhandler(Exception)
    def handle_unhandled(error):
        app.logger.exception(error)
        return jsonify({"error": "Internal Server Error", "message": "An unexpected error occurred"}), 500

from flask import Blueprint, jsonify, request
from flask_jwt_extended import create_access_token, get_jwt_identity, jwt_required
from werkzeug.security import check_password_hash, generate_password_hash

from .extensions import db
from .models import User

auth_bp = Blueprint("auth", __name__)


def _validate_required(data, fields):
    missing = [f for f in fields if not data.get(f)]
    if missing:
        return missing
    return None


@auth_bp.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}

    missing = _validate_required(data, ["username", "email", "password"])
    if missing:
        return jsonify({"error": "Validation Error", "message": f"Missing fields: {', '.join(missing)}"}), 400

    username = data["username"].strip()
    email = data["email"].strip().lower()
    password = data["password"]

    if len(password) < 6:
        return jsonify({"error": "Validation Error", "message": "Password must be at least 6 characters"}), 400

    if User.query.filter_by(username=username).first():
        return jsonify({"error": "Conflict", "message": "Username already exists"}), 409

    if User.query.filter_by(email=email).first():
        return jsonify({"error": "Conflict", "message": "Email already exists"}), 409

    user = User(
        username=username,
        email=email,
        password_hash=generate_password_hash(password),
    )
    db.session.add(user)
    db.session.commit()

    access_token = create_access_token(identity=str(user.id))
    return jsonify({"user": user.to_dict(), "access_token": access_token}), 201


@auth_bp.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}

    missing = _validate_required(data, ["username", "password"])
    if missing:
        return jsonify({"error": "Validation Error", "message": f"Missing fields: {', '.join(missing)}"}), 400

    username = data["username"].strip()
    password = data["password"]

    user = User.query.filter_by(username=username).first()
    if not user or not check_password_hash(user.password_hash, password):
        return jsonify({"error": "Unauthorized", "message": "Invalid username or password"}), 401

    access_token = create_access_token(identity=str(user.id))
    return jsonify({"user": user.to_dict(), "access_token": access_token}), 200


@auth_bp.route("/me", methods=["GET"])
@jwt_required()
def me():
    user_id = int(get_jwt_identity())
    user = User.query.get(user_id)
    if not user:
        return jsonify({"error": "Not Found", "message": "User not found"}), 404
    return jsonify(user.to_dict()), 200

from datetime import datetime

from flask import Blueprint, jsonify, request
from flask_jwt_extended import get_jwt_identity, jwt_required
from sqlalchemy import or_

from .extensions import db
from .models import Task, User

tasks_bp = Blueprint("tasks", __name__)

MAX_PER_PAGE = 100
DEFAULT_PER_PAGE = 10


def _current_user_id():
    return int(get_jwt_identity())


def _parse_due_date(value):
    if value in (None, ""):
        return None
    if isinstance(value, str):
        return datetime.strptime(value, "%Y-%m-%d").date()
    return value


def _get_user_or_404(user_id):
    user = db.session.get(User, user_id)
    if not user:
        return None
    return user


@tasks_bp.route("", methods=["GET"])
@jwt_required()
def list_tasks():
    query = Task.query

    status = request.args.get("status")
    priority = request.args.get("priority")
    category = request.args.get("category")
    assignee_id = request.args.get("assignee_id")
    search = request.args.get("q") or request.args.get("search")

    if status:
        query = query.filter(Task.status == status)
    if priority:
        query = query.filter(Task.priority == priority)
    if category:
        query = query.filter(Task.category == category)
    if assignee_id:
        query = query.filter(Task.assignee_id == int(assignee_id))
    if search:
        like = f"%{search}%"
        query = query.filter(or_(Task.title.ilike(like), Task.description.ilike(like)))

    page = request.args.get("page", 1, type=int)
    per_page = request.args.get("per_page", DEFAULT_PER_PAGE, type=int)
    if page < 1:
        page = 1
    if per_page < 1 or per_page > MAX_PER_PAGE:
        per_page = DEFAULT_PER_PAGE

    pagination = query.order_by(Task.created_at.desc()).paginate(
        page=page, per_page=per_page, error_out=False
    )

    return jsonify({
        "items": [task.to_dict() for task in pagination.items],
        "total": pagination.total,
        "page": pagination.page,
        "per_page": pagination.per_page,
        "pages": pagination.pages,
    }), 200


@tasks_bp.route("", methods=["POST"])
@jwt_required()
def create_task():
    data = request.get_json(silent=True) or {}

    if not data.get("title"):
        return jsonify({"error": "Validation Error", "message": "title is required"}), 400

    status = data.get("status", "pending")
    priority = data.get("priority", "medium")

    if status not in Task.STATUSES:
        return jsonify({"error": "Validation Error", "message": f"status must be one of {list(Task.STATUSES)}"}), 400
    if priority not in Task.PRIORITIES:
        return jsonify({"error": "Validation Error", "message": f"priority must be one of {list(Task.PRIORITIES)}"}), 400

    due_date = data.get("due_date")
    try:
        due_date = _parse_due_date(due_date)
    except ValueError:
        return jsonify({"error": "Validation Error", "message": "due_date must be in YYYY-MM-DD format"}), 400

    assignee_id = data.get("assignee_id")
    if assignee_id is not None:
        if not _get_user_or_404(assignee_id):
            return jsonify({"error": "Not Found", "message": "Assignee not found"}), 404
        assignee_id = int(assignee_id)

    task = Task(
        title=data["title"].strip(),
        description=data.get("description"),
        status=status,
        priority=priority,
        category=data.get("category"),
        due_date=due_date,
        creator_id=_current_user_id(),
        assignee_id=assignee_id,
    )
    db.session.add(task)
    db.session.commit()

    return jsonify(task.to_dict()), 201


@tasks_bp.route("/<int:task_id>", methods=["GET"])
@jwt_required()
def get_task(task_id):
    task = db.session.get(Task, task_id)
    if not task:
        return jsonify({"error": "Not Found", "message": "Task not found"}), 404
    return jsonify(task.to_dict()), 200


@tasks_bp.route("/<int:task_id>", methods=["PUT"])
@jwt_required()
def update_task(task_id):
    task = db.session.get(Task, task_id)
    if not task:
        return jsonify({"error": "Not Found", "message": "Task not found"}), 404

    data = request.get_json(silent=True) or {}

    if "title" in data:
        if not data.get("title"):
            return jsonify({"error": "Validation Error", "message": "title cannot be empty"}), 400
        task.title = data["title"].strip()

    if "description" in data:
        task.description = data.get("description")

    if "status" in data:
        status = data["status"]
        if status not in Task.STATUSES:
            return jsonify({"error": "Validation Error", "message": f"status must be one of {list(Task.STATUSES)}"}), 400
        task.status = status

    if "priority" in data:
        priority = data["priority"]
        if priority not in Task.PRIORITIES:
            return jsonify({"error": "Validation Error", "message": f"priority must be one of {list(Task.PRIORITIES)}"}), 400
        task.priority = priority

    if "category" in data:
        task.category = data.get("category")

    if "due_date" in data:
        try:
            task.due_date = _parse_due_date(data.get("due_date"))
        except ValueError:
            return jsonify({"error": "Validation Error", "message": "due_date must be in YYYY-MM-DD format"}), 400

    if "assignee_id" in data:
        assignee_id = data.get("assignee_id")
        if assignee_id is None:
            task.assignee_id = None
        else:
            if not _get_user_or_404(assignee_id):
                return jsonify({"error": "Not Found", "message": "Assignee not found"}), 404
            task.assignee_id = int(assignee_id)

    db.session.commit()
    return jsonify(task.to_dict()), 200


@tasks_bp.route("/<int:task_id>", methods=["DELETE"])
@jwt_required()
def delete_task(task_id):
    task = db.session.get(Task, task_id)
    if not task:
        return jsonify({"error": "Not Found", "message": "Task not found"}), 404
    db.session.delete(task)
    db.session.commit()
    return jsonify({"message": "Task deleted"}), 200


@tasks_bp.route("/<int:task_id>/assign", methods=["POST"])
@jwt_required()
def assign_task(task_id):
    task = db.session.get(Task, task_id)
    if not task:
        return jsonify({"error": "Not Found", "message": "Task not found"}), 404

    data = request.get_json(silent=True) or {}
    assignee_id = data.get("assignee_id")
    if assignee_id is None:
        return jsonify({"error": "Validation Error", "message": "assignee_id is required"}), 400

    if not _get_user_or_404(assignee_id):
        return jsonify({"error": "Not Found", "message": "Assignee not found"}), 404

    task.assignee_id = int(assignee_id)
    db.session.commit()
    return jsonify(task.to_dict()), 200

